function randomPuzzle(bank){let p=bank[Math.floor(Math.random()*bank.length)],n=p.n,flipX=Math.random()<.5,flipY=Math.random()<.5,transpose=Math.random()<.5;let colors=Array.from({length:n},(_,i)=>i);for(let i=n-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[colors[i],colors[j]]=[colors[j],colors[i]]}let regions=Array(n*n),solution=Array(n);for(let r=0;r<n;r++)for(let c=0;c<n;c++){let x=flipY?n-1-r:r,y=flipX?n-1-c:c;if(transpose)[x,y]=[y,x];regions[x*n+y]=colors[p.regions[r*n+c]];if(p.solution[r]===c)solution[x]=y}return {n,regions,solution}}let LEVELS=BANKS.map(randomPuzzle);function newRun(){LEVELS=BANKS.map(randomPuzzle)}